class Solution {
    public int maxArea(int[] height) {
        int res = 0;
        int L = 0;
        int R = height.length-1;
        while(L<R){
            res = Math.max(res,(R-L) * Math.min(height[L],height[R]));
            if(height[L]<height[R]){
                L++;
            }else{
                R--;
            }
        }
        return res;
    }
}
